/**
 * Writes `crates/research-html/src/entities_data.rs`: entities 8.1.0's packed
 * HTML decode trie as a Rust array, so the Rust decoder walks the very data
 * htmlparser2 walks (ADR-0030 decision 6).
 *
 *     node scripts/vectors/html/writeEntityTrie.ts
 *
 * `vectors/html/entities.json` carries the trie's length and SHA-256; the
 * Rust vector test fails when the generated file and the package diverge.
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { htmlDecodeTree } from "./htmlparser2.ts";

const target = fileURLToPath(
	new URL("../../../crates/research-html/src/entities_data.rs", import.meta.url),
);
const words = Array.from(htmlDecodeTree, (word) => `0x${word.toString(16).padStart(4, "0")}`);
const lines: string[] = [];
for (let index = 0; index < words.length; index += 12) {
	lines.push(`\t${words.slice(index, index + 12).join(", ")},`);
}
const source = `//! GENERATED by \`node scripts/vectors/html/writeEntityTrie.ts\` from entities 8.1.0
//! (\`htmlDecodeTree\`, the trie htmlparser2 12.0.0 decodes with). Do not edit.
//!
//! Layout (see entities' \`internal/bin-trie-flags.ts\`): each node starts with a
//! header word — bits 15..14 value length + 1, bit 13 "semicolon required"
//! (or "compact run" when there is no value), bits 12..7 branch count, bits
//! 6..0 jump-table offset / single-branch character.

/// The packed HTML named-character-reference trie (${words.length} words).
#[rustfmt::skip]
pub(crate) static HTML_DECODE_TREE: [u16; ${words.length}] = [
${lines.join("\n")}
];
`;
writeFileSync(target, source);
console.log(`wrote ${target} (${words.length} words)`);
